declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$me=dn_member_by_id($db,$uid);if(!$me||!in_array((string)$me['role'],['admin','moderator'],true)){nxt_status_page(403,'Restricted terminal','This terminal is available to administrators and moderators.');}$counts=[];foreach(['members','digimon_species','digimon_instances','digimon_scan','messages','clans','trade_listings','battle_log','arena_battles'] as $table){$r=$db->query('SELECT COUNT(*) c FROM `'.$table.'`');$counts[$table]=$r?(int)$r->fetch_assoc()['c']:0;}$online=0;$r=$db->query('SELECT COUNT(*) c FROM online WHERE time>='.(time()-900));if($r)$online=(int)$r->fetch_assoc()['c'];$schema='?';$r=$db->query("SELECT meta_value FROM schema_meta WHERE meta_key='schema_version' LIMIT 1");if($r&&($x=$r->fetch_assoc()))$schema=(string)$x['meta_value'];pv_page_start('Administration','your_account.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('your_account.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">NXT SERVER CONTROL // <?=pv_h(strtoupper((string)$me['role']))?></span><h1>Administration</h1><p class="pv-subtle">Monitor Digimon NXT accounts, network activity and game data.</p></div><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('_health.php'))?>">Health Endpoint</a></div><div class="dn-stat-strip"><div><span>Schema</span><strong><?=pv_h($schema)?></strong></div><div><span>Tamers</span><strong><?=$counts['members']?></strong></div><div><span>Online</span><strong><?=$online?></strong></div><div><span>Digimon</span><strong><?=$counts['digimon_instances']?></strong></div></div><section class="pv-card" style="padding:18px;margin-top:14px"><h2>Database object counts</h2><?php foreach($counts as $k=>$v):?><div class="pv-status-row"><span><?=pv_h($k)?></span><strong><?=number_format($v)?></strong></div><?php endforeach;?></section><section class="pv-card" style="padding:18px;margin-top:14px"><h2>Installation resources</h2><p>The complete standalone SQL dump is bundled outside the web root at <code>database/digimon_nxt_full.sql</code>. The local <code>_setup.php</code> utility can also create, migrate, repair or freshly rebuild the same schema.</p></section></section></main></div><?php pv_page_end(); ?>
